end--[[APR_DIAG]]; module.ApplyBarFill = APRTrace("APR-Core/integrations/EllesmereUISkin.lua:107:module:ApplyBarFill#8", module.ApplyBarFill)--[[/APR_DIAG]]

function module:ApplyHeaderTextColor(fontString, scope)
